KANJI.add(5,[{"k":"一","l":5,"ch":1,"hv":"NHẤT","m":"Số một; một","on":["イチ","イツ"],"kun":["ひと-","ひと.つ"],"s":1,"r":1,"rd":[1],"p":[],"ls":"CS","o":"Chỉ sự (指事): một vạch ngang đơn giản để biểu thị khái niệm trừu tượng “một”, không vẽ hình vật cụ thể. Chữ này đồng thời là gốc của chuỗi số 一・二・三 ở Giáp cốt văn, được xếp bằng que tính.¶Thuyết văn giải tự đặt 一 làm bộ đầu tiên, coi đó là khởi điểm của vạn vật; vì vậy 一 còn mang nghĩa “nhất, đầu tiên, toàn bộ” (一生, 一番).","a":0,"en":["one","one radical (no.1)"],"f":[]},{"k":"二","l":5,"ch":1,"hv":"NHỊ","m":"Số hai","on":["ニ","ジ"],"kun":["ふた","ふた.つ","ふたたび"],"s":2,"r":7,"rd":[7],"p":[["一","NHẤT","Số một; nét ngang",""],["一","NHẤT","Số một; nét ngang",""]],"ls":"CS","o":"Chỉ sự: hai vạch ngang chồng lên nhau, biểu thị số hai. Vạch trên thường ngắn hơn vạch dưới trong chữ cổ, về sau mới viết gần bằng nhau.¶Cách xếp que tính này tạo nên nhóm 一・二・三, ba chữ số đầu tiên của Hán tự.","a":0,"en":["two","two radical (no. 7)"],"f":[]},{"k":"三","l":5,"ch":1,"hv":"TAM","m":"Số ba","on":["サン","ゾウ"],"kun":["み","み.つ","みっ.つ"],"s":3,"r":1,"rd":[1,7],"p":[["一","NHẤT","Số một; nét ngang",""],["二","NHỊ","Số hai",""]],"ls":"CS","o":"Chỉ sự: ba vạch ngang, biểu thị số ba. Thuyết văn giải thích 三 là “đạo của trời, đất, người”, nên ba còn gợi ý niệm “đầy đủ, trọn vẹn” (三才: Thiên, Địa, Nhân).¶Dạng 三 và 王 (ba vạch ngang nối bởi một vạch dọc) khác nhau ở nét dọc; đừng nhầm hai chữ này.","a":0,"en":["three"],"f":[]},{"k":"四","l":5,"ch":1,"hv":"TỨ","m":"Số bốn","on":["シ"],"kun":["よ","よ.つ","よっ.つ","よん"],"s":5,"r":31,"rd":[10,31],"p":[["囗","VI","Vây quanh; khung vuông",""],["儿","NHÂN","Chân người; người đi",""]],"ls":"GT","o":"Giáp cốt văn viết số bốn bằng bốn vạch ngang (亖), cùng kiểu với 一二三. Dạng 四 ngày nay là một chữ khác (khung 囗 chứa 八, Thuyết văn giải là hình “bốn phần chia ra”) được mượn dùng làm số bốn, nên thuộc loại giả tá (假借).¶Đây là lý do 四 không còn giữ lối xếp vạch của 一二三.","a":0,"en":["four"],"f":["囗"]},{"k":"五","l":5,"ch":1,"hv":"NGŨ","m":"Số năm","on":["ゴ"],"kun":["いつ","いつ.つ"],"s":4,"r":7,"rd":[7],"p":[["一","NHẤT","Số một; nét ngang",""],["𫝀","","",""]],"ls":"CS","o":"Giáp cốt văn viết 五 là một chữ X kẹp giữa hai vạch ngang, tức dấu giao nhau giữa trời và đất (hai vạch) với âm dương, ngũ hành đan chéo (dấu X). Về sau hai vạch được nối thành dạng 五 hiện nay.¶Thuyết văn giải: “五, ngũ hành vậy, từ nhị, âm dương giao nhau ở giữa”. Vì vậy 五 ăn khớp với các nhóm năm như 五行, 五感.","a":0,"en":["five"],"f":[]},{"k":"六","l":5,"ch":1,"hv":"LỤC","m":"Số sáu","on":["ロク","リク"],"kun":["む","む.つ","むっ.つ","むい"],"s":4,"r":12,"rd":[8,12],"p":[["亠","ĐẦU","Cái nắp; mái đầu",""],["八","BÁT","Số tám; chia ra",""]],"ls":"GT","o":"Theo một giả thuyết phổ biến, Giáp cốt văn vẽ hình túp lều có mái (廬 là chữ phái sinh), vốn không liên quan đến số lượng.¶Số sáu được biểu thị bằng cách mượn âm và hình chữ này, nên 六 thuộc giả tá.","a":0,"en":["six"],"f":[]},{"k":"七","l":5,"ch":1,"hv":"THẤT","m":"Số bảy","on":["シチ"],"kun":["なな","なな.つ","なの"],"s":2,"r":1,"rd":[1],"p":[["㇀","","",""],["乚","ẤT","Can thứ hai; nét gập","乙"]],"ls":"GT","o":"Giáp cốt văn viết 七 giống dấu cộng (十), một nét ngang với một nét dọc cắt qua; sau này nét dọc uốn cong để khác với 十. Chữ gốc mang nghĩa “cắt”, về sau mới có chữ 切 (cắt) ra đời để thay thế phần nghĩa này.¶Con số bảy được biểu thị bằng cách mượn chữ 七, nên thuộc giả tá. Thuyết văn giải 七 là “dương khí vi chính, mà âm khí còn uốn khúc bên dưới”, nhưng giải thích này mang tính triết lý hơn là từ nguyên.","a":0,"en":["seven"],"f":["七"]},{"k":"八","l":5,"ch":1,"hv":"BÁT","m":"Số tám","on":["ハチ","ハツ"],"kun":["や","や.つ","やっ.つ","よう"],"s":2,"r":12,"rd":[12],"p":[],"ls":"GT","o":"Hình hai nét tách ra hai bên, nghĩa gốc là “chia ra, phân chia” (Thuyết văn: “八, biệt dã”). Nghĩa này còn trong 分 (八 + 刀: dùng dao chia) và 半 (八 + 牛: chia đôi con bò).¶Số tám được biểu thị bằng cách mượn hình chữ, nên thuộc giả tá. 八 cũng xuất hiện như một bộ thủ phụ trong nhiều chữ khác.","a":0,"en":["eight","eight radical (no. 12)"],"f":[]},{"k":"九","l":5,"ch":1,"hv":"CỬU","m":"Số chín","on":["キュウ","ク"],"kun":["ここの","ここの.つ"],"s":2,"r":5,"rd":[5],"p":[["乙","ẤT","Can thứ hai; nét gập",""]],"ls":"GT","o":"Giáp cốt văn vẽ hình cánh tay co lại ở khuỷu (khuỷu tay, 肘 là chữ phái sinh về sau). Con số chín được biểu thị bằng cách mượn hình chữ này (giả tá).¶Chín là số dương lớn nhất trong một chữ số, nên 九 còn mang nghĩa “nhiều, cùng cực” trong văn cổ (九天, 九死).","a":0,"en":["nine"],"f":["九"]},{"k":"十","l":5,"ch":1,"hv":"THẬP","m":"Số mười; trọn vẹn","on":["ジュウ","ジッ","ジュッ"],"kun":["とお","と","そ"],"s":2,"r":24,"rd":[24],"p":[],"ls":"CS","o":"Giáp cốt văn viết số mười chỉ bằng một nét dọc (丨), tượng trưng sợi dây thắt nút theo cách ghi chép cổ. Về sau thêm chấm ở giữa nét rồi kéo thành nét ngang, tạo dạng chữ thập 十.¶Đây là chữ chỉ sự: không vẽ vật, mà dùng nét đơn giản để biểu thị số lượng. 十 đồng thời là bộ thủ trong nhiều chữ như 古, 千, 半.","a":0,"en":["ten"],"f":["十"]},{"k":"百","l":5,"ch":1,"hv":"BÁCH","m":"Trăm","on":["ヒャク","ビャク"],"kun":["もも"],"s":6,"r":106,"rd":[106],"p":[["一","NHẤT","Số một; nét ngang",""],["白","BẠCH","Màu trắng",""]],"ls":"HT","o":"Thuyết văn giải 百 gồm 一 và 白, trong đó 白 gợi âm (白 đọc gần với 百: ハク/ヒャク). 一 ở trên có thể là nét chỉ số “một trăm”.¶Cách cấu tạo này cho thấy 百 là chữ hình thanh: phần 白 chỉ âm (ハク ~ ヒャク), nét 一 ở trên đánh dấu đây là số lượng. Cùng kiểu tạo số lớn với 千 (人 + 一).","a":0,"en":["hundred"],"f":["白"]},{"k":"千","l":5,"ch":1,"hv":"THIÊN","m":"Nghìn","on":["セン"],"kun":["ち"],"s":3,"r":24,"rd":[24],"p":[["丿","PHIỆT","Nét phẩy",""],["十","THẬP","Số mười",""]],"ls":"HT","o":"Thuyết văn giải: 千 gồm 十 (gợi nghĩa số lượng) và 人 (gợi âm, nhân ~ thiên). Giáp cốt văn viết là 人 thêm một nét ngang (一) ở chân hoặc ngang thân, biểu thị “nghìn người”.¶Cách viết cho thấy chữ số đơn vị lớn được tạo từ chữ 人 cộng nét chỉ số, giống như 百 (一 + 白) và 万. Cùng một kiểu tạo số lớn trong chữ Hán.","a":0,"en":["thousand"],"f":["千"]},{"k":"万","l":5,"ch":1,"hv":"VẠN","m":"Mười nghìn; vạn","on":["マン","バン"],"kun":["よろず"],"s":3,"r":1,"rd":[1],"p":[["一","NHẤT","Số một; nét ngang",""],["丿","PHIỆT","Nét phẩy",""],["𠃌","","",""]],"ls":"GT","o":"Chữ gốc là 萬, vẽ hình con bọ cạp (đầu có càng, đuôi cong). Vì âm đọc giống từ “vạn”, người xưa mượn hình bọ cạp để viết số 10.000 (giả tá).¶万 là chữ cổ đã tồn tại từ lâu và được dùng làm dạng giản của 萬 trong tiếng Nhật; nghĩa “mười nghìn” và nghĩa phái sinh “rất nhiều” (万能) cùng thuộc nguồn này.","a":0,"en":["ten thousand","10,000"],"f":["万"]},{"k":"円","l":5,"ch":1,"hv":"VIÊN","m":"Yên (tiền Nhật); hình tròn","on":["エン"],"kun":["まる.い","まる","まど","まど.か","まろ.やか"],"s":4,"r":13,"rd":[13],"p":[["冂","QUYNH","Vùng biên giới xa; khung",""]],"ls":"HT","o":"Dạng gốc là 圓 (viên), cấu tạo từ 囗 (khung vây quanh) và 員 (viên, gợi âm); nghĩa là hình tròn. 円 là dạng giản lược mà tiếng Nhật dùng thay cho 圓.¶Ở Nhật, đồng tiền cận đại có hình tròn nên 円 trở thành đơn vị tiền tệ “yên” từ thời Minh Trị (1871). Nghĩa gốc “tròn” vẫn còn trong 円形.","a":0,"en":["circle","yen","round"],"f":[]},{"k":"月","l":5,"ch":2,"hv":"NGUYỆT","m":"Mặt trăng; tháng","on":["ゲツ","ガツ"],"kun":["つき"],"s":4,"r":74,"rd":[74],"p":[],"ls":"TH","o":"Tượng hình (象形): vẽ hình mặt trăng khuyết, có nét trong để phân biệt với 日. Giáp cốt văn có khi viết thêm chấm bên trong; hình lưỡi liềm là gốc của chữ.¶Khi làm thành tố bên trái trong các chữ về cơ thể (肝, 腕, 脳), chữ 月 thường là dạng biến của 肉 (thịt), không phải “mặt trăng”. Trong các chữ chỉ thời gian (明, 期), 月 mới đúng là mặt trăng.","a":0,"en":["month","moon"],"f":[]},{"k":"火","l":5,"ch":2,"hv":"HỎA","m":"Lửa","on":["カ"],"kun":["ひ","-び","ほ-"],"s":4,"r":86,"rd":[86],"p":[["八","BÁT","Số tám; chia ra",""],["人","NHÂN","Người",""]],"ls":"TH","o":"Tượng hình: vẽ ngọn lửa bốc lên với những ngọn lửa nhọn. Giáp cốt văn viết ba ngọn lửa trên một đống củi, về sau giản lược thành nét giữa và hai chấm hai bên.¶Khi ở dưới chữ khác, 火 biến thành bốn chấm 灬 (như 熱, 無). Phần nghĩa “nóng, cháy, nổ” (火事, 火山) đều xuất phát từ hình ngọn lửa.","a":0,"en":["fire"],"f":["火"]},{"k":"水","l":5,"ch":2,"hv":"THỦY","m":"Nước","on":["スイ"],"kun":["みず","みず-"],"s":4,"r":85,"rd":[85],"p":[["㇇","","",""],["亅","QUYẾT","Nét móc",""],["乀","PHIỆT","Nét phẩy","丿"],["丿","PHIỆT","Nét phẩy",""]],"ls":"TH","o":"Tượng hình: vẽ dòng nước chảy, nét giữa là dòng chính và hai bên là gợn nước tung ra. Giáp cốt văn có khi giữ hình giọt nước bắn quanh dòng chảy.¶Khi làm bộ bên trái, 水 rút thành 氵 (ba chấm thủy) như trong 海, 池, 泳. Đây là bộ thủ số 85, một trong những bộ thủ dùng nhiều nhất.","a":0,"en":["water"],"f":["水"]},{"k":"木","l":5,"ch":2,"hv":"MỘC","m":"Cây; gỗ","on":["ボク","モク"],"kun":["き","こ-"],"s":4,"r":75,"rd":[75],"p":[],"ls":"TH","o":"Tượng hình: vẽ một cái cây với thân thẳng, cành mở phía trên và rễ xòe phía dưới. Nét ngang là cành, nét xiên hai bên là rễ.¶木 là bộ thủ số 75 và là thành tố của vô số chữ về cây cối (林, 森, 校, 桜), vật liệu và đồ gỗ. Ghép hai và ba lần thành 林 (rừng), 森 (rừng rậm).","a":0,"en":["tree","wood"],"f":[]},{"k":"金","l":5,"ch":2,"hv":"KIM","m":"Vàng; kim loại; tiền","on":["キン","コン","ゴン"],"kun":["かね","かな-","-がね"],"s":8,"r":167,"rd":[167],"p":[["人","NHÂN","Người",""],["王","NGỌC","Ngọc","玉"],["丷","BÁT","Số tám; chia ra","八"]],"ls":"HT","o":"Thuyết văn giải: 金 từ 土 (đất), hai chấm bên trong chỉ các mẩu kim loại nằm trong đất, và 今 (kim) vừa gợi âm. Giáp cốt văn là hình khối đồng (tiền đồng đúc).¶Nghĩa mở rộng từ “kim loại” sang “vàng” và “tiền” (お金, 金曜日: thứ sáu, ứng với sao Kim trong ngũ hành).","a":0,"en":["gold"],"f":["王","金"]},{"k":"土","l":5,"ch":2,"hv":"THỔ","m":"Đất","on":["ド","ト"],"kun":["つち"],"s":3,"r":32,"rd":[32],"p":[["十","THẬP","Số mười",""],["一","NHẤT","Số một; nét ngang",""]],"ls":"TH","o":"Tượng hình: Giáp cốt văn vẽ một cục đất đắp thành gò trên mặt đất (một nét ngang là mặt đất). Hình gò đất này về sau thành nét dọc đặt trên nét ngang.¶土 là bộ thủ số 32, chỉ đất, nền, địa điểm (地, 坂, 場). Trong ngũ hành, 土 là thổ, mang nghĩa “mặt đất, đất đai” (土地, 土曜日).","a":0,"en":["soil","earth","ground"],"f":[]},{"k":"日","l":5,"ch":2,"hv":"NHẬT","m":"Mặt trời; ngày","on":["ニチ","ジツ"],"kun":["ひ","-び","-か"],"s":4,"r":72,"rd":[72],"p":[],"ls":"TH","o":"Tượng hình: vẽ mặt trời tròn với một chấm hoặc nét ở giữa. Vì khắc trên xương và mai rùa khó vẽ tròn, hình vuông hóa thành 日 như hiện nay.¶Từ “mặt trời” nghĩa mở rộng sang “ngày” (日曜日, 毎日) và “Nhật Bản” (日本, nơi mặt trời mọc). Là bộ thủ số 72 trong các chữ về thời gian (時, 明, 昨).","a":0,"en":["day","sun","Japan"],"f":[]},{"k":"年","l":5,"ch":2,"hv":"NIÊN","m":"Năm","on":["ネン"],"kun":["とし"],"s":6,"r":51,"rd":[51],"p":[["干","CAN","Khô; can dự",""]],"ls":"HT","o":"Thuyết văn giải 年 là chữ hình thanh (禾 + 千), nghĩa gốc là lúa chín. Giáp cốt văn và Kim văn viết 年 là hình người cõng bó lúa (禾 + 人), tức mùa gặt.¶Vì lúa chín mỗi năm một vụ, “mùa gặt” chuyển nghĩa thành “năm”. Dạng hiện nay có thể xem như hội ý hoặc hình thanh tùy cách giải.","a":0,"en":["year","counter for years"],"f":[]},{"k":"人","l":5,"ch":3,"hv":"NHÂN","m":"Người","on":["ジン","ニン"],"kun":["ひと","-り","-と"],"s":2,"r":9,"rd":[9],"p":[],"ls":"TH","o":"Tượng hình: vẽ người nhìn nghiêng, hơi cúi người và đưa tay ra trước. Giáp cốt văn là hình đường nét với hai chân và cánh tay.¶人 là bộ thủ số 9; khi làm bộ bên trái, rút thành 亻 (nhân đứng) như trong 休, 体, 何. Nhiều chữ chỉ người, quan hệ và hành động của người đều mang bộ này.","a":0,"en":["person"],"f":[]},{"k":"口","l":5,"ch":3,"hv":"KHẨU","m":"Miệng; cửa","on":["コウ","ク"],"kun":["くち"],"s":3,"r":30,"rd":[30],"p":[],"ls":"TH","o":"Tượng hình: vẽ cái miệng há ra, hình vuông trên Giáp cốt văn. Nghĩa mở rộng thành “cửa, lối ra vào” (出口, 入口) và “số người” (人口).¶Là bộ thủ số 30, 口 xuất hiện trong các chữ liên quan đến nói, ăn, kêu (名, 言, 古, 呼). Đừng nhầm 口 (miệng) với 囗 (khung vây quanh) có kích thước lớn hơn.","a":0,"en":["mouth"],"f":[]},{"k":"目","l":5,"ch":3,"hv":"MỤC","m":"Mắt","on":["モク","ボク"],"kun":["め","-め","ま-"],"s":5,"r":109,"rd":[109],"p":[],"ls":"TH","o":"Tượng hình: vẽ con mắt với đồng tử ở giữa. Giáp cốt văn viết 目 nằm ngang, giống con mắt nhìn thẳng; để tiện khắc, về sau xoay dựng đứng thành 目.¶目 là bộ thủ số 109, xuất hiện trong chữ về nhìn, mắt (見, 直, 眼, 相). Nghĩa mở rộng thành “mục, hạng mục” (目的, 項目).","a":0,"en":["eye","class","look"],"f":["目"]},{"k":"耳","l":5,"ch":3,"hv":"NHĨ","m":"Tai","on":["ジ"],"kun":["みみ"],"s":6,"r":128,"rd":[128],"p":[],"ls":"TH","o":"Tượng hình: vẽ cái tai với vành ngoài và lỗ tai. Dạng cổ giống một vòng cong lớn với nét nhỏ bên trong.¶Bộ thủ số 128; 耳 xuất hiện trong chữ về nghe (聞, 聴, 職). 耳 cũng gợi nghĩa “bên cạnh, nghe lỏm”.","a":0,"en":["ear"],"f":["耳"]},{"k":"手","l":5,"ch":3,"hv":"THỦ","m":"Tay","on":["シュ","ズ"],"kun":["て","て-","-て","た-"],"s":4,"r":64,"rd":[64],"p":[],"ls":"TH","o":"Tượng hình: vẽ bàn tay với năm ngón và cổ tay. Hình cổ có ngón mở rộng; chữ giản lược chỉ còn ba nét ngang và nét sổ móc.¶Khi làm bộ bên trái, 手 rút thành 扌 (tài gảy), như trong 持, 打, 投. Nghĩa mở rộng thành “người làm nghề” (歌手, 運転手) và “phương tiện” (手段).","a":0,"en":["hand"],"f":["手"]},{"k":"足","l":5,"ch":3,"hv":"TÚC","m":"Chân; đủ","on":["ソク"],"kun":["あし","た.りる","た.る","た.す"],"s":7,"r":157,"rd":[157],"p":[["口","KHẨU","Cái miệng",""],["龰","","",""]],"ls":"TH","o":"Tượng hình: Giáp cốt văn vẽ cẳng chân gồm 口 (đầu gối) và 止 (bàn chân) nối liền. Thuyết văn: “人之足也” (cái chân của người).¶Là bộ thủ số 157 (⻊ khi làm bộ bên trái), xuất hiện trong chữ về chân, đi, chạy (路, 跳, 踊). Nghĩa mở rộng thành “đủ, thỏa” (足りる).","a":0,"en":["leg","foot","be sufficient"],"f":["足"]},{"k":"力","l":5,"ch":3,"hv":"LỰC","m":"Sức lực","on":["リョク","リキ","リイ"],"kun":["ちから"],"s":2,"r":19,"rd":[19],"p":[["丿","PHIỆT","Nét phẩy",""],["𠃌","","",""]],"ls":"TH","o":"Tượng hình: Giáp cốt văn vẽ cái cày gỗ nhọn dùng xới đất (một giải thích thịnh hành), cũng có thuyết cho rằng đó là cánh tay gồng gân. Thuyết văn giải “gân cơ của người”.¶Bộ thủ số 19, đứng trong nhiều chữ chỉ sức lực và nỗ lực (男, 加, 助, 動). Gốc nông nghiệp của chữ giải thích vì sao 男 là “người dùng sức làm ruộng”.","a":0,"en":["power","strength","strong"],"f":[]},{"k":"山","l":5,"ch":4,"hv":"SƠN","m":"Núi","on":["サン","セン"],"kun":["やま"],"s":3,"r":46,"rd":[46],"p":[],"ls":"TH","o":"Tượng hình: vẽ ba đỉnh núi nhô lên từ một nền. Giáp cốt văn viết ba ngọn nhọn, sau này nét chân nối lại thành 山.¶Bộ thủ số 46. Xuất hiện trong chữ về núi và địa hình (岩, 岡, 島, 崎). Chữ dùng trong 富士山 và nhiều tên địa danh Nhật.","a":0,"en":["mountain"],"f":["山"]},{"k":"川","l":5,"ch":4,"hv":"XUYÊN","m":"Sông","on":["セン"],"kun":["かわ"],"s":3,"r":47,"rd":[47],"p":[],"ls":"TH","o":"Tượng hình: vẽ dòng sông chảy giữa hai bờ. Giáp cốt văn viết ba nét uốn lượn hoặc một dòng nước giữa hai bờ.¶川 là chữ “sông”, khác với 水 (nước nói chung). Dạng 巛 là biến thể cổ; hình 川 ngày nay là hai bờ với một dòng nước ở giữa.","a":0,"en":["stream","river","river or three-stroke river radical (no. 47)"],"f":["川"]},{"k":"田","l":5,"ch":4,"hv":"ĐIỀN","m":"Ruộng lúa","on":["デン"],"kun":["た"],"s":5,"r":102,"rd":[102],"p":[],"ls":"TH","o":"Tượng hình: Giáp cốt văn vẽ thửa ruộng chia thành các ô vuông, có bờ ngăn nhau theo chiều dọc và ngang. Hình “井 điền” gợi hệ thống chia ruộng thời cổ.¶Bộ thủ số 102, xuất hiện trong chữ về ruộng, canh tác (町, 畑, 男, 留). 男 là ghép 田 (ruộng) với 力 (sức).","a":0,"en":["rice field","rice paddy"],"f":["田"]},{"k":"石","l":5,"ch":4,"hv":"THẠCH","m":"Đá","on":["セキ","シャク","コク"],"kun":["いし"],"s":5,"r":112,"rd":[112],"p":[["丆","","",""],["口","KHẨU","Cái miệng",""]],"ls":"TH","o":"Tượng hình: gồm 厂 (vách đá, sườn núi) và 口 (một hòn đá rơi xuống). Thuyết văn giải: “山石之形”, tức hình tảng đá dưới vách núi.¶Bộ thủ số 112, xuất hiện trong chữ về đá, khoáng vật (岩, 砂, 研). Nghĩa mở rộng thành các vật cứng và nặng.","a":0,"en":["stone"],"f":["石"]},{"k":"花","l":5,"ch":4,"hv":"HOA","m":"Hoa","on":["カ","ケ"],"kun":["はな"],"s":7,"r":140,"rd":[9,21,140],"p":[["艹","THẢO","Cỏ","艸"],["化","HÓA","Biến hóa",""]],"ls":"HT","o":"Hình thanh: 艹 (bộ cỏ, chỉ loài thực vật) chỉ nghĩa, 化 (hóa, biến đổi) gợi âm. 化 vừa gợi âm vừa gợi ý: hoa là cây biến đổi sắc hương khi nở.¶Chữ 花 xuất hiện muộn, đời Nam Bắc triều; trước đó người ta dùng 華 để chỉ hoa. Về sau 花 thay thế dần chữ 華 trong nghĩa “hoa”.","a":0,"en":["flower"],"f":["化"]},{"k":"竹","l":5,"ch":4,"hv":"TRÚC","m":"Tre","on":["チク"],"kun":["たけ"],"s":6,"r":118,"rd":[118],"p":[["亇","","",""],["亇","","",""]],"ls":"TH","o":"Tượng hình: vẽ hai nhánh tre với lá rủ xuống. Giáp cốt văn viết hai cụm lá treo như hình chữ 个 gấp đôi.¶Là bộ thủ số 118 (⺮ khi nằm trên), xuất hiện trong chữ về tre trúc và đồ đan, văn phòng phẩm cổ (筆, 箱, 算, 笛).","a":0,"en":["bamboo"],"f":["竹"]},{"k":"雨","l":5,"ch":4,"hv":"VŨ","m":"Mưa","on":["ウ"],"kun":["あめ","あま-","-さめ"],"s":8,"r":173,"rd":[173],"p":[["一","NHẤT","Số một; nét ngang",""],["𠕒","","",""]],"ls":"TH","o":"Tượng hình: nét ngang là bầu trời, hình 冂 là tầng mây, các chấm bên dưới là hạt mưa rơi xuống. Giáp cốt văn viết các giọt mưa nối thành dòng.¶Bộ thủ số 173, xuất hiện trong chữ về hiện tượng khí tượng (雪, 雲, 電, 霧). Nghĩa mở rộng thành “rơi xuống nhiều” trong 雨天.","a":0,"en":["rain"],"f":["雨"]},{"k":"上","l":5,"ch":5,"hv":"THƯỢNG","m":"Trên","on":["ジョウ","ショウ","シャン"],"kun":["うえ","-うえ","うわ-","かみ","あ.げる","-あ.げる","あ.がる","-あ.がる","あ.がり","-あ.がり","のぼ.る","のぼ.り","のぼ.せる","のぼ.す","たてまつ.る"],"s":3,"r":1,"rd":[1],"p":[["⺊","","",""],["一","NHẤT","Số một; nét ngang",""]],"ls":"CS","o":"Chỉ sự: Giáp cốt văn viết một vạch dài (mặt chuẩn) với một vạch ngắn ở phía trên, chỉ vị trí “trên”. Dạng hiện nay thêm nét sổ để thành 上.¶Cùng cách với 下 (vạch ngắn nằm dưới vạch dài). Từ vị trí vật lý, nghĩa mở rộng thành địa vị cao hơn, “lên” và “trước” (上手, 向上).","a":0,"en":["above","up"],"f":[]},{"k":"下","l":5,"ch":5,"hv":"HẠ","m":"Dưới","on":["カ","ゲ"],"kun":["した","しも","もと","さ.げる","さ.がる","くだ.る","くだ.り","くだ.す","-くだ.す","くだ.さる","お.ろす","お.りる"],"s":3,"r":1,"rd":[1,25],"p":[["一","NHẤT","Số một; nét ngang",""],["卜","BỐC","Xem bói",""]],"ls":"CS","o":"Chỉ sự: đối xứng với 上, vạch ngắn nằm dưới vạch dài (mặt chuẩn) để chỉ vị trí “dưới”. Giáp cốt văn là một vòng cung mở ra với một nét nhỏ bên dưới.¶Nghĩa mở rộng thành “xuống, thấp, kém hơn” (下がる, 下手). 上 và 下 là cặp chữ chỉ sự điển hình nhất.","a":0,"en":["below","down","descend"],"f":[]},{"k":"左","l":5,"ch":5,"hv":"TẢ","m":"Trái","on":["サ","シャ"],"kun":["ひだり"],"s":5,"r":48,"rd":[48],"p":[["𠂇","","",""],["工","CÔNG","Thợ; công việc",""]],"ls":"HY","o":"Giáp cốt văn chỉ vẽ bàn tay trái (ナ). Về sau thêm 工 (cái thước, dụng cụ) để chỉ tay trái giúp tay phải cầm dụng cụ làm việc, thành hội ý (从ナ从工).¶Hai chữ 左 và 右 dùng chung gốc tay (ナ/又) nhưng thêm 工 hoặc 口 để phân biệt, nên khi viết cần nhớ nét ngang ngắn của 左 so với 右.","a":0,"en":["left"],"f":["左","工"]},{"k":"右","l":5,"ch":5,"hv":"HỮU","m":"Phải","on":["ウ","ユウ"],"kun":["みぎ"],"s":5,"r":30,"rd":[30],"p":[["𠂇","","",""],["口","KHẨU","Cái miệng",""]],"ls":"HY","o":"Giáp cốt văn chỉ vẽ bàn tay phải (又). Về sau thêm 口 (miệng) để chỉ tay phải gắp thức ăn đưa lên miệng, thành hội ý.¶Cách giải này giải thích sự phân biệt 左 (thêm 工) và 右 (thêm 口) chính là phân công việc cho tay trái và tay phải.","a":0,"en":["right"],"f":["右"]},{"k":"外","l":5,"ch":5,"hv":"NGOẠI","m":"Bên ngoài","on":["ガイ","ゲ"],"kun":["そと","ほか","はず.す","はず.れる","と-"],"s":5,"r":36,"rd":[25,36],"p":[["夕","TỊCH","Buổi tối",""],["卜","BỐC","Xem bói",""]],"ls":"HY","o":"Hội ý: 夕 (buổi tối) và 卜 (bói). Thuyết văn giải: người xưa xem bói vào ban ngày; bói vào buổi tối là bất thường, “ngoài lệ”, nên 夕 + 卜 có nghĩa “bên ngoài”.¶Nghĩa mở rộng thành “ngoài, ngoại quốc” (外国, 外人), đối lập với 内 (bên trong).","a":0,"en":["outside"],"f":["夕"]},{"k":"内","l":5,"ch":5,"hv":"NỘI","m":"Bên trong","on":["ナイ","ダイ"],"kun":["うち"],"s":4,"r":13,"rd":[9,13],"p":[["冂","QUYNH","Vùng biên giới xa; khung",""],["人","NHÂN","Người",""]],"ls":"HY","o":"Hội ý: 冂 (cái nhà, vùng bao quanh) với 入 (đi vào), nghĩa gốc là “vào trong nhà”. Thuyết văn: “入也, từ 冂 từ 入”.¶Nghĩa mở rộng thành “bên trong, nội bộ” (内側, 国内), đối lập với 外.","a":0,"en":["inside","within","between"],"f":["内"]},{"k":"中","l":5,"ch":5,"hv":"TRUNG","m":"Giữa; bên trong","on":["チュウ"],"kun":["なか","うち","あた.る"],"s":4,"r":2,"rd":[2,30],"p":[["口","KHẨU","Cái miệng",""],["丨","CỔN","Nét sổ thẳng",""]],"ls":"TH","o":"Giáp cốt văn viết một ô vuông (vòng) bị nét dọc xuyên qua giữa, hoặc là lá cờ có cán xuyên qua tâm hình tròn. Đây là chữ tượng hình chỉ vị trí chính giữa, nơi cờ hiệu dựng ở trung tâm.¶Nghĩa mở rộng thành “giữa, trong, trúng” (中心, 中学, 的中) và còn dùng như tên nước 中国.","a":0,"en":["in","inside","middle"],"f":["中"]},{"k":"学","l":5,"ch":6,"hv":"HỌC","m":"Học","on":["ガク"],"kun":["まな.ぶ"],"s":8,"r":39,"rd":[14,39],"p":[["𭕄","","",""],["冖","MỊCH","Trùm khăn; che phủ",""],["子","TỬ","Con; đứa trẻ",""]],"ls":"HY","o":"Dạng gốc 學: 臼 (hai bàn tay) trao cho nhau 爻 (hào, các nét giao nhau tượng trưng tri thức) bên dưới mái nhà 冖, và 子 (đứa trẻ) ở dưới. Hội ý: người lớn truyền tri thức cho trẻ em trong trường.¶Dạng 学 là cách giản lược của 學, phần trên ⺍ là dạng rút gọn của hai bàn tay (臼) và 爻, kèm mái nhà và 子.","a":0,"en":["study","learning","science"],"f":["子"]},{"k":"校","l":5,"ch":6,"hv":"HIỆU","m":"Trường học","on":["コウ","キョウ"],"kun":[],"s":10,"r":75,"rd":[8,75,88],"p":[["木","MỘC","Cây; gỗ",""],["交","GIAO","Giao nhau; trao đổi",""]],"ls":"HT","o":"Hình thanh: 木 (gỗ) chỉ nghĩa, 交 (giao) gợi âm. Nghĩa gốc là hàng rào, khung gỗ hoặc xiềng gỗ; từ đó mở rộng sang “so sánh, kiểm tra” (校正) và “nơi dạy học” (学校) vì xưa trường học dựng bằng gỗ rào.¶Ghi nhớ: 校 xuất hiện trong 学校, 校庭, 校長, đều liên quan đến trường.","a":0,"en":["exam","school","printing"],"f":["交"]},{"k":"先","l":5,"ch":6,"hv":"TIÊN","m":"Trước; đi trước","on":["セン"],"kun":["さき","ま.ず"],"s":6,"r":10,"rd":[10],"p":[["𠂒","","",""],["儿","NHÂN","Chân người; người đi",""]],"ls":"HY","o":"Giáp cốt văn viết 之 (hình bàn chân, chỉ sự đi tới) trên đầu 人. Hội ý: người đi phía trước, đến trước người khác.¶Nghĩa mở rộng thành “trước” (先月, 先に), “tiền bối” và “thầy” (先生). Ghép với 生 thành 先生: người sinh ra trước, người đi trước trên đường học vấn.","a":0,"en":["before","ahead","previous"],"f":["先"]},{"k":"生","l":5,"ch":6,"hv":"SINH","m":"Sống; sinh ra","on":["セイ","ショウ"],"kun":["い.きる","い.かす","い.ける","う.まれる","うま.れる","う.まれ","うまれ","う.む","お.う","は.える","は.やす","き","なま","なま-","な.る","な.す","む.す","-う"],"s":5,"r":100,"rd":[100],"p":[],"ls":"HY","o":"Giáp cốt văn vẽ mầm cây (屮) mọc lên từ mặt đất (一). Thuyết văn: “象草木生出土上”. Nghĩa gốc là sinh ra, mọc lên.¶Từ đó 生 có hàng loạt nghĩa: “sống” (生きる), “sinh” (生まれる), “tươi” (生), “học sinh” (生徒). Là một trong những chữ có nhiều cách đọc nhất.","a":0,"en":["life","genuine","birth"],"f":["生"]},{"k":"名","l":5,"ch":6,"hv":"DANH","m":"Tên; danh tiếng","on":["メイ","ミョウ"],"kun":["な","-な"],"s":6,"r":30,"rd":[30,36],"p":[["夕","TỊCH","Buổi tối",""],["口","KHẨU","Cái miệng",""]],"ls":"HY","o":"Hội ý: 夕 (buổi tối) và 口 (miệng). Thuyết văn giải: ban đêm tối không nhìn rõ nhau, phải dùng miệng xưng tên để người khác biết mình là ai.¶Từ “xưng tên” nghĩa mở rộng thành “tên” (名前), “danh tiếng” (有名) và “người” khi đếm (三名).","a":0,"en":["name","noted","distinguished"],"f":["名","夕"]},{"k":"字","l":5,"ch":6,"hv":"TỰ","m":"Chữ","on":["ジ"],"kun":["あざ","あざな","-な"],"s":6,"r":39,"rd":[39,40],"p":[["宀","MIÊN","Mái nhà",""],["子","TỬ","Con; đứa trẻ",""]],"ls":"HY","o":"Hội ý: 宀 (mái nhà) và 子 (đứa trẻ). Nghĩa gốc là “sinh con, nuôi con trong nhà”; chữ 子 còn gợi âm. Từ nghĩa “sinh sôi” chuyển thành “chữ viết”, vì chữ mới được sinh ra từ chữ cũ (Thuyết văn: “文生而孳乳浸多, 故謂之字”).¶Vì vậy trong chữ Hán, 文 là chữ đơn giản, còn 字 là chữ phái sinh nhiều thành phần.","a":0,"en":["character","letter","word"],"f":["子","宀"]},{"k":"本","l":5,"ch":6,"hv":"BẢN","m":"Sách; gốc; quyển","on":["ホン"],"kun":["もと"],"s":5,"r":75,"rd":[75],"p":[["木","MỘC","Cây; gỗ",""]],"ls":"CS","o":"Chỉ sự: 木 (cây) với một nét ngang ở gốc, chỉ vị trí rễ cây. Nghĩa gốc là “gốc cây”.¶Từ “gốc” chuyển nghĩa thành “nguồn gốc, căn bản” (基本, 本当), “cuốn sách” (本) vì sách là gốc của tri thức, và “đơn vị đếm vật dài” (一本). So sánh với 末 (nét ngang ở ngọn, nghĩa “cuối”).","a":0,"en":["book","present","main"],"f":["本"]},{"k":"体","l":5,"ch":6,"hv":"THỂ","m":"Cơ thể","on":["タイ","テイ"],"kun":["からだ","かたち"],"s":7,"r":9,"rd":[9],"p":[["亻","NHÂN","Người","人"],["本","BẢN","Sách; gốc; quyển",""]],"ls":"HT","o":"Dạng truyền thống là 體: 骨 (xương) chỉ nghĩa, 豊 (phong, lễ) gợi âm, nghĩa là thân thể. Tiếng Nhật dùng 体, vốn là một chữ riêng (người + gốc, 人 + 本), nghĩa gốc là “thô, vụng”, mượn làm dạng giản của 體.¶Ghi nhớ hiện đại: 体 gồm 人 (người) + 本 (gốc), “gốc của con người là thân thể”, dù đây chỉ là cách nhớ, không phải từ nguyên.","a":0,"en":["body","substance","object"],"f":["本"]},{"k":"大","l":5,"ch":7,"hv":"ĐẠI","m":"To lớn","on":["ダイ","タイ"],"kun":["おお-","おお.きい","-おお.いに"],"s":3,"r":37,"rd":[37],"p":[["一","NHẤT","Số một; nét ngang",""],["人","NHÂN","Người",""]],"ls":"TH","o":"Tượng hình: vẽ một người đứng thẳng, dang rộng hai tay và hai chân. Người dang hết cỡ gợi ý niệm “to lớn”.¶Từ hình người trưởng thành, 大 mang nghĩa “lớn” (大きい), “nhiều”, “quan trọng” (大切). Cũng là gốc của nhiều chữ: 天, 夫, 立, 太.","a":0,"en":["large","big"],"f":["大"]},{"k":"小","l":5,"ch":7,"hv":"TIỂU","m":"Nhỏ","on":["ショウ"],"kun":["ちい.さい","こ-","お-","さ-"],"s":3,"r":42,"rd":[42],"p":[],"ls":"CS","o":"Chỉ sự: Giáp cốt văn viết ba chấm nhỏ (hạt cát, hạt nhỏ) để biểu thị “nhỏ”. Về sau thành một nét sổ với hai chấm hai bên.¶Thuyết văn giải 小 là hình “八 phân chia vật” (một vật nhỏ lại bị chia). Đối lập với 大. Nghĩa mở rộng thành “nhỏ, ít, trẻ” (小学校, 小さい).","a":0,"en":["little","small"],"f":["小"]},{"k":"高","l":5,"ch":7,"hv":"CAO","m":"Cao; đắt","on":["コウ"],"kun":["たか.い","たか","-だか","たか.まる","たか.める"],"s":10,"r":189,"rd":[189],"p":[["亠","ĐẦU","Cái nắp; mái đầu",""],["口","KHẨU","Cái miệng",""],["冋","","",""]],"ls":"TH","o":"Tượng hình: Giáp cốt văn vẽ lầu cao có mái nhọn bên trên, thân lầu bên dưới và cổng ở dưới đáy. Hình 亠 là nóc, 冂 là thân, 口 là cửa.¶Nghĩa mở rộng thành “cao” (高い), “đắt” (高い), “cao quý” (高校, 高級). Các nghĩa này đều xuất phát từ hình tòa lầu vượt cao hơn xung quanh.","a":0,"en":["tall","high","expensive"],"f":["冋","高"]},{"k":"友","l":5,"ch":7,"hv":"HỮU","m":"Bạn bè","on":["ユウ"],"kun":["とも"],"s":4,"r":29,"rd":[29],"p":[["𠂇","","",""],["又","HỰU","Lại nữa; bàn tay phải",""]],"ls":"HY","o":"Giáp cốt văn vẽ hai bàn tay phải (又 + 又) chồng lên nhau, biểu thị hai người nắm tay, giúp đỡ nhau. Thuyết văn: “同志為友”, cùng chí hướng thì là bạn.¶Dạng 友 hiện nay là một bàn tay (ナ) chồng lên bàn tay phải (又). Ghép với 人 thành 友人 (người bạn).","a":0,"en":["friend"],"f":["又","友"]},{"k":"入","l":5,"ch":7,"hv":"NHẬP","m":"Vào","on":["ニュウ","ジュ"],"kun":["い.る","-い.る","-い.り","い.れる","-い.れ","はい.る"],"s":2,"r":11,"rd":[11],"p":[],"ls":"TH","o":"Tượng hình: Giáp cốt văn vẽ hình mũi nhọn đi sâu vào, cũng được giải là lối vào nhà. Nghĩa gốc là “đi vào”.¶Đối lập với 出. Cần phân biệt 入 (vào) với 人 (người) và 八 (tám): 入 có nét phẩy dài hơn nét mác, 人 thì ngược lại.","a":0,"en":["enter","insert"],"f":[]},{"k":"出","l":5,"ch":7,"hv":"XUẤT","m":"Ra; đi ra","on":["シュツ","スイ"],"kun":["で.る","-で","だ.す","-だ.す","い.でる","い.だす"],"s":5,"r":17,"rd":[17,45],"p":[["屮","TRIỆT","Mầm cây",""],["凵","KHẢM","Há miệng; cái hố",""]],"ls":"HY","o":"Giáp cốt văn viết 止 (bàn chân) đi ra khỏi 凵 (cái hang, hố). Hội ý: bước chân ra khỏi nơi trú ẩn. Dạng cổ có hình cây mầm nảy ra, Thuyết văn giải “草木益滋, 上出達也”.¶Nghĩa mở rộng thành “ra, xuất” (出る, 出口, 出発), đối lập với 入.","a":0,"en":["exit","leave","go out"],"f":["出"]},{"k":"門","l":5,"ch":7,"hv":"MÔN","m":"Cổng","on":["モン"],"kun":["かど","と"],"s":8,"r":169,"rd":[169],"p":[["𠁣","","",""],["𠃛","","",""]],"ls":"TH","o":"Tượng hình: Giáp cốt văn vẽ hai cánh cổng đối xứng với hai cột và thanh ngang phía trên. Dạng hiện nay giữ hình hai cánh cửa mở.¶Bộ thủ số 169, xuất hiện trong chữ về cổng và hoạt động liên quan (開, 閉, 間, 聞). Nghĩa mở rộng thành “cổng, ngành, môn” (専門, 部門).","a":0,"en":["gate","counter for cannons"],"f":["門"]},{"k":"父","l":5,"ch":8,"hv":"PHỤ","m":"Cha","on":["フ"],"kun":["ちち"],"s":4,"r":88,"rd":[88],"p":[["八","BÁT","Số tám; chia ra",""],["乂","","",""]],"ls":"HY","o":"Giáp cốt văn viết bàn tay (又) cầm một cây rìu đá hay cái gậy (丨). Hội ý (hay tượng hình): người cha cầm công cụ dẫn dắt, săn bắt và lao động.¶Thuyết văn giải “矩也, 家長率教者”, người trong nhà dẫn dắt và dạy bảo con cháu. Cùng nhóm với 母 (mẹ), 子 (con).","a":0,"en":["father"],"f":["父"]},{"k":"母","l":5,"ch":8,"hv":"MẪU","m":"Mẹ","on":["ボ"],"kun":["はは","も"],"s":5,"r":80,"rd":[80],"p":[],"ls":"TH","o":"Tượng hình: biến thể của 女 (người phụ nữ quỳ), thêm hai chấm biểu thị bầu vú nuôi con. Giáp cốt văn là người nữ quỳ có nhấn mạnh ngực.¶Hai chấm ấy là điểm phân biệt 母 với 女, và cũng là điểm làm 母 khác 毋. Nghĩa mở rộng thành “gốc, nguồn” (母国, 母音).","a":0,"en":["mother"],"f":[]},{"k":"子","l":5,"ch":8,"hv":"TỬ","m":"Con cái; đứa trẻ","on":["シ","ス","ツ"],"kun":["こ","-こ","ね"],"s":3,"r":39,"rd":[39],"p":[],"ls":"TH","o":"Tượng hình: vẽ đứa trẻ có đầu to, hai tay giơ lên và hai chân quấn trong tã. Giáp cốt văn có hình đứa bé trong tã lót.¶Nghĩa mở rộng thành “con”, “người” (男子, 女子), “hạt giống” (種子), và thành tiếng tôn xưng (孔子, 孟子). Là bộ thủ số 39.","a":0,"en":["child","sign of the rat","11PM-1AM"],"f":["子"]},{"k":"男","l":5,"ch":8,"hv":"NAM","m":"Đàn ông; nam","on":["ダン","ナン"],"kun":["おとこ","お"],"s":7,"r":102,"rd":[19,102],"p":[["田","ĐIỀN","Ruộng",""],["力","LỰC","Sức mạnh",""]],"ls":"HY","o":"Hội ý: 田 (ruộng) và 力 (sức, cái cày). Người đàn ông dùng sức làm ruộng. Thuyết văn: “丈夫也, 从田从力, 言男用力於田也”.¶Trong xã hội nông nghiệp cổ, phân công lao động giữa nam (ngoài đồng) và nữ (trong nhà) được lưu lại ngay trong chữ.","a":0,"en":["male"],"f":["男","田"]},{"k":"女","l":5,"ch":8,"hv":"NỮ","m":"Phụ nữ; nữ","on":["ジョ","ニョ","ニョウ"],"kun":["おんな","め"],"s":3,"r":38,"rd":[38],"p":[],"ls":"TH","o":"Tượng hình: vẽ người phụ nữ quỳ gối, hai tay đặt trước ngực. Giáp cốt văn thể hiện tư thế ngồi nhẹ nhàng của người nữ.¶Là bộ thủ số 38, xuất hiện trong chữ về phụ nữ, quan hệ gia đình, tính cách (好, 安, 姉, 妹, 嫁). Nhiều chữ cổ chứa 女 phản ánh quan điểm xã hội xưa.","a":0,"en":["woman","female"],"f":[]},{"k":"犬","l":5,"ch":8,"hv":"KHUYỂN","m":"Con chó","on":["ケン"],"kun":["いぬ","いぬ-"],"s":4,"r":94,"rd":[94],"p":[],"ls":"TH","o":"Tượng hình: vẽ con chó với thân thon, đuôi cong, đầu ngẩng. Giáp cốt văn viết đứng, nhìn nghiêng.¶Khi làm bộ bên trái, 犬 rút thành 犭 (khuyển), như trong 狼, 独, 猫. Đừng nhầm với 大 (to) và 太 (rất to): 犬 có thêm một chấm ở vai.","a":0,"en":["dog"],"f":["犬"]},{"k":"鳥","l":5,"ch":8,"hv":"ĐIỂU","m":"Con chim","on":["チョウ"],"kun":["とり"],"s":11,"r":196,"rd":[196],"p":[["灬","HỎA","Lửa","火"]],"ls":"TH","o":"Tượng hình: vẽ con chim với đầu, mỏ, cánh và đuôi dài. Giáp cốt văn mô tả rõ lông và chân.¶Khác với 隹 (chim đuôi ngắn). Bộ thủ số 196; trong các chữ 鳴, 鶏, 鴨, 鳥 chỉ nhóm chim nói chung. Bốn chấm 灬 phía dưới vốn là chân và đuôi chim, không phải lửa.","a":0,"en":["bird","chicken"],"f":["鳥","灬"]},{"k":"立","l":5,"ch":9,"hv":"LẬP","m":"Đứng; dựng","on":["リツ","リュウ","リットル"],"kun":["た.つ","-た.つ","た.ち-","た.てる","-た.てる","た.て-","たて-","-た.て","-だ.て","-だ.てる"],"s":5,"r":117,"rd":[117],"p":[["亠","ĐẦU","Cái nắp; mái đầu",""],["丷","BÁT","Số tám; chia ra","八"],["一","NHẤT","Số một; nét ngang",""]],"ls":"HY","o":"Hội ý: 大 (người dang rộng tay chân) đứng trên 一 (mặt đất). Giáp cốt văn vẽ hình người đứng trên một nét ngang.¶Nghĩa mở rộng thành “đứng” (立つ), “dựng lên” (建立, 国立), và “thiết lập”. Là bộ thủ số 117.","a":0,"en":["stand up","rise","set up"],"f":["立"]},{"k":"休","l":5,"ch":9,"hv":"HƯU","m":"Nghỉ ngơi","on":["キュウ"],"kun":["やす.む","やす.まる","やす.める"],"s":6,"r":9,"rd":[9,75],"p":[["亻","NHÂN","Người","人"],["木","MỘC","Cây; gỗ",""]],"ls":"HY","o":"Hội ý: 人 (người) dựa vào 木 (cây). Hình ảnh người dựa lưng nghỉ dưới gốc cây. Giáp cốt văn viết rõ người tựa thân cây.¶Từ đó 休 có nghĩa “nghỉ ngơi” (休む, 休日), cũng mở rộng thành “yên nghỉ, tốt đẹp” (休息). Là một trong những chữ hội ý dễ hiểu nhất.","a":0,"en":["rest","day off","retire"],"f":[]},{"k":"見","l":5,"ch":9,"hv":"KIẾN","m":"Nhìn; thấy","on":["ケン"],"kun":["み.る","み.える","み.せる"],"s":7,"r":147,"rd":[147],"p":[["目","MỤC","Mắt",""],["儿","NHÂN","Chân người; người đi",""]],"ls":"HY","o":"Hội ý: 目 (mắt) lớn đặt trên 儿 (người). Giáp cốt văn nhấn mạnh con mắt trên thân người, biểu thị hành động “nhìn”.¶Bộ thủ số 147. Nghĩa mở rộng thành “thấy, xem, ý kiến” (見る, 意見). 見 cũng xuất hiện trong 親, 視, 現, 規.","a":0,"en":["see","hopes","chances"],"f":["見","目"]},{"k":"聞","l":5,"ch":9,"hv":"VĂN","m":"Nghe; hỏi","on":["ブン","モン"],"kun":["き.く","き.こえる"],"s":14,"r":128,"rd":[128,169],"p":[["門","MÔN","Cổng",""],["耳","NHĨ","Tai",""]],"ls":"HT","o":"Hình thanh: 耳 (tai) chỉ nghĩa, 門 (môn) gợi âm. Nghĩa gốc là “nghe”. Giáp cốt văn viết người bịt tai hoặc đưa tai lắng nghe.¶Nghĩa mở rộng thành “nghe” (聞く) và “hỏi”, “tin tức” (新聞). 門 trong chữ 聞 chỉ gợi âm, không liên quan đến cổng.","a":0,"en":["hear","ask","listen"],"f":["耳","門"]},{"k":"行","l":5,"ch":9,"hv":"HÀNH","m":"Đi; thực hiện","on":["コウ","ギョウ","アン"],"kun":["い.く","ゆ.く","-ゆ.き","-ゆき","-い.き","-いき","おこな.う","おこ.なう"],"s":6,"r":144,"rd":[144],"p":[["彳","XÍCH","Bước chân trái; đi",""],["亍","","",""]],"ls":"TH","o":"Tượng hình: Giáp cốt văn vẽ ngã tư đường với bốn hướng giao nhau. Nghĩa gốc là “đường”, rồi “đi” (行く) và “thực hành” (行為).¶Bộ thủ số 144; khi tách đôi, 彳 (bước chân trái) và 亍 (bước chân phải) là hai nửa của 行, giải thích vì sao chữ về đi lại (往, 後, 待) lại mang 彳.","a":0,"en":["going","journey","carry out"],"f":["行","亍","彳"]},{"k":"来","l":5,"ch":9,"hv":"LAI","m":"Đến","on":["ライ","タイ"],"kun":["く.る","きた.る","きた.す","き.たす","き.たる","き","こ"],"s":7,"r":75,"rd":[75],"p":[["木","MỘC","Cây; gỗ",""]],"ls":"GT","o":"Dạng gốc 來: Giáp cốt văn vẽ cây lúa mạch (麥) với bông và rễ. Về sau mượn hình lúa mạch để viết “đến” do đồng âm (giả tá).¶Truyền thuyết cho rằng lúa mạch là giống trời ban, nên 來 mang nghĩa “đến từ trời”. Dạng 来 là cách giản lược tiếng Nhật.","a":0,"en":["come","due","next"],"f":[]},{"k":"帰","l":5,"ch":9,"hv":"QUY","m":"Về; trở về","on":["キ"],"kun":["かえ.る","かえ.す","おく.る","とつ.ぐ"],"s":10,"r":50,"rd":[14,50],"p":[["丨","CỔN","Nét sổ thẳng",""],["丿","PHIỆT","Nét phẩy",""],["帚","","",""]],"ls":"HT","o":"Dạng gốc 歸: 止 (chân, đi) và 婦 lược bớt (帚, chổi, tượng trưng người phụ nữ nội trợ), 𠂤 gợi âm. Nghĩa gốc là cô gái “về” nhà chồng. Từ đó mở rộng thành “quay về nơi mình thuộc về”.¶Dạng 帰 là cách viết lược nét của 歸 mà tiếng Nhật chuẩn hóa; vẫn còn thấy 帚 (chổi) ở phần dưới.","a":0,"en":["homecoming","arrive at","lead to"],"f":["帚"]},{"k":"米","l":5,"ch":10,"hv":"MỄ","m":"Gạo","on":["ベイ","マイ","メエトル"],"kun":["こめ","よね"],"s":6,"r":119,"rd":[119],"p":[],"ls":"TH","o":"Tượng hình: vẽ hạt gạo, nét ngang là cuống bông, bốn chấm là các hạt rơi xuống quanh một nét dọc. Giáp cốt văn vẽ bông lúa rụng hạt.¶Bộ thủ số 119. Chữ 米 xuất hiện trong chữ về lương thực (粉, 精, 糖, 料). Vì đọc là “bei” nên cũng dùng để chỉ nước Mỹ (米国).","a":0,"en":["rice","USA","metre"],"f":["米"]},{"k":"茶","l":5,"ch":10,"hv":"TRÀ","m":"Trà","on":["チャ","サ"],"kun":[],"s":9,"r":140,"rd":[9,75,140],"p":[["艹","THẢO","Cỏ","艸"],["人","NHÂN","Người",""],["朩","MỘC","Cây; gỗ","木"]],"ls":"HT","o":"Hình thanh: 艹 (cỏ) chỉ nghĩa, 余 (dư, gợi âm) bên dưới. Tên cũ là 荼, một loại cây đắng; đời Đường bớt một nét thành 茶 để chỉ cây chè.¶Chữ đi theo con đường buôn bán sang Nhật cùng văn hóa trà đạo (茶道). Tiếng Quan Thoại đọc “chá”, tiếng Mân Nam đọc “te”; nhờ hai con đường buôn bán mà nhiều ngôn ngữ châu Âu có từ “tea” hoặc “chai”.","a":0,"en":["tea"],"f":["余"]},{"k":"牛","l":5,"ch":10,"hv":"NGƯU","m":"Con bò","on":["ギュウ"],"kun":["うし"],"s":4,"r":93,"rd":[93],"p":[],"ls":"TH","o":"Tượng hình: vẽ đầu con bò nhìn chính diện với hai sừng cong. Giáp cốt văn vẽ rõ cặp sừng và đầu.¶Bộ thủ số 93, xuất hiện trong chữ về gia súc, vật tế (物, 特, 牧). Khi ở bên trái, rút thành 牜.","a":0,"en":["cow"],"f":["牛"]},{"k":"肉","l":5,"ch":10,"hv":"NHỤC","m":"Thịt","on":["ニク"],"kun":["しし"],"s":6,"r":130,"rd":[130],"p":[],"ls":"TH","o":"Tượng hình: vẽ miếng thịt có thớ (các nét bên trong biểu thị vân thịt). Giáp cốt văn viết một lát thịt với vân chạy ngang.¶Khi làm thành tố bên trái trong các chữ về cơ thể (肝, 腕, 脳), 肉 thu gọn thành 月 (nhục) và không liên quan đến mặt trăng.","a":0,"en":["meat"],"f":["肉"]},{"k":"魚","l":5,"ch":10,"hv":"NGƯ","m":"Cá","on":["ギョ"],"kun":["うお","さかな","-ざかな"],"s":11,"r":195,"rd":[195],"p":[["𠂊","","",""],["田","ĐIỀN","Ruộng",""],["灬","HỎA","Lửa","火"]],"ls":"TH","o":"Tượng hình: vẽ con cá với đầu, thân có vảy và đuôi. Giáp cốt văn là hình cá đầy đủ vây và đuôi; về sau phần đuôi biến thành bốn chấm 灬.¶Bộ thủ số 195, xuất hiện trong chữ về cá (鮮, 鯨, 鯉). Bốn chấm dưới 魚 vốn là đuôi, không phải lửa.","a":0,"en":["fish"],"f":["魚","灬","田"]},{"k":"貝","l":5,"ch":10,"hv":"BỐI","m":"Con sò; vỏ sò","on":["バイ"],"kun":["かい"],"s":7,"r":154,"rd":[154],"p":[["目","MỤC","Mắt",""],["八","BÁT","Số tám; chia ra",""]],"ls":"TH","o":"Tượng hình: vẽ con sò có hai mảnh vỏ khép lại. Thời cổ vỏ sò được dùng làm tiền, nên 貝 mang nghĩa “của cải”.¶Bộ thủ số 154, hầu hết chữ chứa 貝 đều chỉ tiền bạc, giao dịch (買, 財, 貧, 賣). Đây là minh chứng rõ nhất cho vai trò của vỏ sò trong nền kinh tế cổ.","a":0,"en":["shellfish"],"f":["目"]},{"k":"好","l":5,"ch":10,"hv":"HẢO","m":"Thích; tốt","on":["コウ"],"kun":["この.む","す.く","よ.い","い.い"],"s":6,"r":38,"rd":[38,39],"p":[["女","NỮ","Phụ nữ",""],["子","TỬ","Con; đứa trẻ",""]],"ls":"HY","o":"Hội ý: 女 (phụ nữ) và 子 (đứa con). Hình người mẹ bế con, biểu thị tình yêu thương và niềm vui. Nghĩa gốc là “tốt, đẹp, yêu thích”.¶Thuyết văn giải “美也”. Nghĩa mở rộng thành “thích, yêu” (好き) và “tốt đẹp” (好意).","a":0,"en":["fond","pleasing","like something"],"f":["子"]},{"k":"物","l":5,"ch":10,"hv":"VẬT","m":"Đồ vật","on":["ブツ","モツ"],"kun":["もの","もの-"],"s":8,"r":93,"rd":[20,93],"p":[["牛","NGƯU","Con trâu; con bò",""],["勿","","",""]],"ls":"HT","o":"Hình thanh: 牛 (bò) chỉ nghĩa, 勿 (vật) gợi âm. Nghĩa gốc là bò có lông nhiều màu, sau mở rộng thành “vật, đồ vật” nói chung.¶Bò là tài sản lớn thời cổ, nên chữ về vật phẩm lấy 牛 làm gốc. Nghĩa mở rộng thành “thứ, đồ” (買い物, 食べ物) và “sự vật” (物事).","a":0,"en":["thing","object","matter"],"f":["勿","牛"]},{"k":"林","l":5,"ch":11,"hv":"LÂM","m":"Rừng thưa","on":["リン"],"kun":["はやし"],"s":8,"r":75,"rd":[75],"p":[["木","MỘC","Cây; gỗ",""],["木","MỘC","Cây; gỗ",""]],"ls":"HY","o":"Hội ý: hai chữ 木 (cây) đứng cạnh nhau, biểu thị nhiều cây thành rừng. Đây là cách tạo chữ lặp thành phần để biểu thị số nhiều.¶Ghép ba 木 thành 森 (rừng rậm). Cách tăng nghĩa theo cấp độ như vậy rất đặc trưng của chữ Hán.","a":0,"en":["grove","forest"],"f":["林"]},{"k":"森","l":5,"ch":11,"hv":"SÂM","m":"Rừng rậm","on":["シン"],"kun":["もり"],"s":12,"r":75,"rd":[75],"p":[["木","MỘC","Cây; gỗ",""],["林","LÂM","Rừng thưa",""]],"ls":"HY","o":"Hội ý: ba chữ 木 xếp theo hình tam giác, biểu thị rừng rậm, cây cối um tùm. Số ba trong chữ Hán thường chỉ “rất nhiều”.¶森 mạnh hơn 林 (hai cây) một bậc. Nghĩa mở rộng thành “rậm rạp, u tịch” (森閑), cũng là họ phổ biến ở Nhật (Mori).","a":0,"en":["forest","woods"],"f":["林"]},{"k":"畑","l":5,"ch":11,"hv":"—","m":"Ruộng (cạn); nương","on":[],"kun":["はた","はたけ","-ばたけ"],"s":9,"r":102,"rd":[86,102],"p":[["火","HỎA","Lửa",""],["田","ĐIỀN","Ruộng",""]],"ls":"HY","o":"Quốc tự (国字) do người Nhật tạo ra, không có trong chữ Hán Trung Quốc. Hội ý: 火 (lửa) + 田 (ruộng), chỉ ruộng khô trồng rau màu, bắt nguồn từ lối đốt rẫy (焼畑) để làm đất canh tác.¶Phân biệt với 田 (ruộng nước trồng lúa): 畑 là đất khô, không nước. Chữ này không có âm On, chỉ có âm Kun はたけ/はた, đúng đặc trưng của quốc tự.","a":0,"en":["farm","field","garden"],"f":["火","田"]},{"k":"岩","l":5,"ch":11,"hv":"NHAM","m":"Đá tảng; vách đá","on":["ガン"],"kun":["いわ"],"s":8,"r":46,"rd":[46,112],"p":[["山","SƠN","Núi",""],["石","THẠCH","Đá",""]],"ls":"HY","o":"Hội ý: 山 (núi) trên 石 (đá). Là cách viết đơn giản của 巖 (nham), nghĩa là tảng đá lớn, vách núi. Hình ảnh đá ở trên núi gợi sự cứng rắn, vững chãi.¶Chữ gốc 巖 phức tạp hơn, nên chữ 岩 trở thành dạng chuẩn tiếng Nhật.","a":0,"en":["boulder","rock","cliff"],"f":["石","山"]},{"k":"音","l":5,"ch":11,"hv":"ÂM","m":"Âm thanh","on":["オン","イン","-ノン"],"kun":["おと","ね"],"s":9,"r":180,"rd":[180],"p":[["立","LẬP","Đứng",""],["日","NHẬT","Mặt trời; ngày",""]],"ls":"CS","o":"Giáp cốt văn viết chữ 言 (lời nói) kèm nét chỉ bên trong miệng, biểu thị âm thanh phát ra từ miệng. Thuyết văn giải 音 là “聲也, 生於心, 有節於外, 謂之音”, tiếng sinh ra từ tâm, có tiết tấu bên ngoài thì gọi là âm.¶Dạng hiện nay là 立 + 日, nhưng đó chỉ là hình biến dạng của 言 + một nét, không phải “mặt trời”.","a":0,"en":["sound","noise"],"f":["音","立"]},{"k":"明","l":5,"ch":11,"hv":"MINH","m":"Sáng; rõ ràng","on":["メイ","ミョウ","ミン"],"kun":["あ.かり","あか.るい","あか.るむ","あか.らむ","あき.らか","あ.ける","-あ.け","あ.く","あ.くる","あ.かす"],"s":8,"r":72,"rd":[72,74],"p":[["日","NHẬT","Mặt trời; ngày",""],["月","NGUYỆT","Mặt trăng; tháng",""]],"ls":"HY","o":"Hội ý: Giáp cốt văn viết 日 (mặt trời) và 月 (mặt trăng) cùng nhau, hoặc 囧 (cửa sổ) và 月 (ánh trăng chiếu qua). Cả hai cách đều biểu thị sự sáng tỏ.¶Nghĩa mở rộng thành “sáng” (明るい), “rõ ràng” (説明), “thông minh” và “ngày mai” (明日, 明朝).","a":0,"en":["bright","light"],"f":["明"]},{"k":"暗","l":5,"ch":11,"hv":"ÁM","m":"Tối","on":["アン"],"kun":["くら.い","くら.む","くれ.る"],"s":13,"r":72,"rd":[72,180],"p":[["日","NHẬT","Mặt trời; ngày",""],["音","ÂM","Âm thanh",""]],"ls":"HT","o":"Hình thanh: 日 (mặt trời) chỉ nghĩa, 音 (âm) gợi âm. Nghĩa là tối tăm, thiếu ánh sáng ban ngày. 音 gợi cả âm đọc (アン ~ オン).¶Đối lập với 明. Nghĩa mở rộng thành “tối, ngầm, mờ” (暗い, 暗記: học thuộc lòng không cần nhìn).","a":0,"en":["darkness","disappear","shade"],"f":["音"]},{"k":"言","l":5,"ch":12,"hv":"NGÔN","m":"Nói; lời nói","on":["ゲン","ゴン"],"kun":["い.う","こと"],"s":7,"r":149,"rd":[149],"p":[],"ls":"CS","o":"Chỉ sự: Giáp cốt văn viết chữ 舌 (lưỡi) hoặc cái miệng với nét thêm phía trên, nhấn mạnh hành động phát ra lời. Thuyết văn giải “直言曰言, 論難曰語”, nói thẳng gọi là 言.¶Bộ thủ số 149 (訁 khi làm bộ bên trái), xuất hiện trong chữ về lời nói (話, 読, 語, 説). Nghĩa mở rộng thành “nói, lời” (言う, 言葉).","a":0,"en":["say","word"],"f":[]},{"k":"書","l":5,"ch":12,"hv":"THƯ","m":"Viết; sách","on":["ショ"],"kun":["か.く","-が.き","-がき"],"s":10,"r":73,"rd":[72,73],"p":[["𦘒","","",""],["一","NHẤT","Số một; nét ngang",""],["日","NHẬT","Mặt trời; ngày",""]],"ls":"HT","o":"Hình thanh: 聿 (cây bút) chỉ nghĩa, 者 (giả) gợi âm. Nghĩa gốc là “viết”. Giáp cốt văn vẽ tay cầm bút.¶Nghĩa mở rộng thành “chữ viết, sách vở, văn thư” (書く, 書道, 辞書). Dạng 書 ngày nay có phần dưới là 日 nhưng nguồn gốc vốn là 者 bị giản lược.","a":0,"en":["write"],"f":[]},{"k":"読","l":5,"ch":12,"hv":"ĐỘC","m":"Đọc","on":["ドク","トク","トウ"],"kun":["よ.む","-よ.み"],"s":14,"r":149,"rd":[10,14,33,149],"p":[["言","NGÔN","Lời nói",""],["売","MẠI","Bán",""]],"ls":"HT","o":"Dạng gốc 讀: 言 (lời nói) chỉ nghĩa, 賣 (mại) gợi âm. Nghĩa gốc là “đọc thành tiếng”. 読 là dạng giản lược tiếng Nhật, thay 賣 bằng 売.¶Nghĩa mở rộng thành “đọc, hiểu” (読む, 読書) và “ngắt câu”. Chữ gợi lại thói quen đọc to văn bản của người xưa.","a":0,"en":["read"],"f":["売"]},{"k":"話","l":5,"ch":12,"hv":"THOẠI","m":"Nói chuyện; câu chuyện","on":["ワ"],"kun":["はな.す","はなし"],"s":13,"r":149,"rd":[135,149],"p":[["言","NGÔN","Lời nói",""],["舌","THIỆT","Cái lưỡi",""]],"ls":"HT","o":"Hình thanh: 言 (lời nói) chỉ nghĩa, 舌 (thiệt) gợi âm (舌 xưa đọc gần với 話). Nghĩa gốc là “nói chuyện, câu chuyện”.¶Nghĩa mở rộng thành “nói, chuyện” (話す, 電話, 会話). Dù chứa 舌 (lưỡi), nhưng 舌 chỉ gợi âm là chính, nghĩa phụ là cái lưỡi dùng để nói.","a":0,"en":["tale","talk"],"f":["舌"]},{"k":"食","l":5,"ch":12,"hv":"THỰC","m":"Ăn","on":["ショク","ジキ"],"kun":["く.う","く.らう","た.べる","は.む"],"s":9,"r":184,"rd":[184],"p":[["人","NHÂN","Người",""],["良","LƯƠNG","Tốt",""]],"ls":"HY","o":"Hội ý: Giáp cốt văn viết 亼 (cái nắp, miệng há) trên 皀 (chén đựng cơm đầy). Hình ảnh một chén cơm với cái miệng bên trên, biểu thị việc ăn.¶Bộ thủ số 184 (飠 khi làm bộ bên trái), xuất hiện trong chữ về đồ ăn thức uống (飲, 飯, 飼, 館). Nghĩa mở rộng thành “ăn” (食べる) và “thức ăn” (食物).","a":0,"en":["eat","food"],"f":["食","良"]},{"k":"飲","l":5,"ch":12,"hv":"ẨM","m":"Uống","on":["イン","オン"],"kun":["の.む","-の.み"],"s":12,"r":184,"rd":[76,184],"p":[["飠","THỰC","Ăn","食"],["欠","KHIẾM","Thiếu; ngáp",""]],"ls":"HT","o":"Hình thanh: 食 (ăn) chỉ nghĩa, 欠 (người há miệng) vừa chỉ hành động. Thuyết văn giải “從欠酓聲”: 欠 chỉ nghĩa, 酓 gợi âm. Nghĩa là uống.¶Hình người há miệng uống (欠) bên cạnh 食 cho thấy 飲 là hành động đưa chất lỏng vào miệng. Nghĩa mở rộng thành “uống” (飲む, 飲料).","a":0,"en":["drink","smoke","take"],"f":["飠","欠"]},{"k":"買","l":5,"ch":12,"hv":"MÃI","m":"Mua","on":["バイ"],"kun":["か.う"],"s":12,"r":154,"rd":[122,154],"p":[["罒","VÕNG","Cái lưới","网"],["貝","BỐI","Vỏ sò; tiền của",""]],"ls":"HY","o":"Hội ý: 网 (lưới) bên trên và 貝 (vỏ sò, tiền). Hình ảnh “dùng lưới vớt tiền”, nghĩa là lấy được của cải bằng cách trả tiền, tức mua.¶So sánh với 売 (bán), cũng chứa 貝 nhưng thêm 士, đối lập với 買. Cả hai chữ cho thấy tiền bạc được biểu thị bằng vỏ sò.","a":0,"en":["buy"],"f":["罒"]},{"k":"町","l":5,"ch":13,"hv":"ĐINH","m":"Thị trấn; phố","on":["チョウ"],"kun":["まち"],"s":7,"r":102,"rd":[102],"p":[["田","ĐIỀN","Ruộng",""],["丁","ĐINH","Khu phố; số đếm",""]],"ls":"HT","o":"Hình thanh: 田 (ruộng) chỉ nghĩa, 丁 (đinh) gợi âm. Nghĩa gốc là bờ ruộng, đường giữa các thửa ruộng; từ đó chuyển thành “khu phố, thị trấn”.¶Nghĩa này phát triển riêng ở Nhật. 町 là đơn vị hành chính (町, まち) và đơn vị đo chiều dài cổ (khoảng 109 m).","a":0,"en":["town","village","block"],"f":["丁","田"]},{"k":"寺","l":5,"ch":13,"hv":"TỰ","m":"Chùa","on":["ジ"],"kun":["てら"],"s":6,"r":41,"rd":[32,41],"p":[["土","THỔ","Đất",""],["寸","THỐN","Tấc (đơn vị đo)",""]],"ls":"HT","o":"Hình thanh: 寸 (tay) chỉ nghĩa, 之 (chi, gợi âm; nay biến thành 土). Nghĩa gốc là “giữ, cầm” (đồng nguyên với 持), rồi chỉ “cơ quan quan lại”.¶Thời Hán, chùa Bạch Mã đón sư Ấn Độ ở cơ quan 鴻臚寺 nên 寺 mang nghĩa “chùa Phật”. Đây là con đường lịch sử khiến một chữ chỉ quan thự thành chỉ nơi thờ Phật.","a":0,"en":["Buddhist temple"],"f":["寺","寸"]},{"k":"電","l":5,"ch":13,"hv":"ĐIỆN","m":"Điện","on":["デン"],"kun":[],"s":13,"r":173,"rd":[72,173],"p":[["雨","VŨ","Mưa",""],["日","NHẬT","Mặt trời; ngày",""],["乚","ẤT","Can thứ hai; nét gập","乙"]],"ls":"HY","o":"Hội ý: 雨 (mưa) và 申 (tia chớp, hình ảnh sét xé trời). Thuyết văn giải “陰陽激耀也”. Nghĩa gốc là “sét”.¶Nghĩa mở rộng thành “điện” trong khoa học cận đại (電気, 電話, 電車). Chữ 電 được dùng làm yếu tố tạo thuật ngữ khoa học hiện đại (電気, 電池, 電子).","a":0,"en":["electricity"],"f":["雨"]},{"k":"車","l":5,"ch":13,"hv":"XA","m":"Xe","on":["シャ"],"kun":["くるま"],"s":7,"r":159,"rd":[159],"p":[],"ls":"TH","o":"Tượng hình: Giáp cốt văn vẽ chiếc xe nhìn từ trên xuống với hai bánh, trục ngang và càng xe. Dạng hiện nay là hình xe nhìn từ trên xuống, nét ngang giữa là trục.¶Bộ thủ số 159, xuất hiện trong chữ về xe và vận chuyển (軍, 転, 輸, 輪). Nghĩa mở rộng thành “xe” (車, 電車, 自動車).","a":0,"en":["car"],"f":["車"]},{"k":"東","l":5,"ch":13,"hv":"ĐÔNG","m":"Phía đông","on":["トウ"],"kun":["ひがし"],"s":8,"r":75,"rd":[75],"p":[["木","MỘC","Cây; gỗ",""]],"ls":"HY","o":"Thuyết văn giải: 日 (mặt trời) ở giữa 木 (cây), tức mặt trời mọc xuyên qua cành cây, hướng Đông. Tuy nhiên Giáp cốt văn vẽ cái bao đựng đồ buộc hai đầu, và nghĩa “phương Đông” là mượn âm (giả tá).¶Dù từ nguyên có thể khác, cách giải “mặt trời mọc sau cây” là cách nhớ truyền thống.","a":0,"en":["east"],"f":["東"]},{"k":"西","l":5,"ch":13,"hv":"TÂY","m":"Phía tây","on":["セイ","サイ","ス"],"kun":["にし"],"s":6,"r":146,"rd":[10,30,146],"p":[["一","NHẤT","Số một; nét ngang",""],["𠁤","","",""]],"ls":"GT","o":"Giáp cốt văn vẽ cái tổ chim hoặc giỏ đan. Thuyết văn giải “鳥在巢上”: chim đậu trên tổ khi mặt trời lặn. Nghĩa “phương Tây” đến từ việc mượn hình này (giả tá).¶Chữ này không thể tách thành thành tố có nghĩa trong tiếng Nhật hiện đại; dạng 西 là dạng cuối cùng sau nhiều thay đổi.","a":0,"en":["west","Spain"],"f":[]},{"k":"南","l":5,"ch":13,"hv":"NAM","m":"Phía nam","on":["ナン","ナ"],"kun":["みなみ"],"s":9,"r":24,"rd":[12,13,24,51],"p":[["十","THẬP","Số mười",""],["冂","QUYNH","Vùng biên giới xa; khung",""],["𢆉","","",""]],"ls":"GT","o":"Giáp cốt văn vẽ một nhạc cụ (chuông hoặc trống treo) của người phương Nam. Nghĩa “phương Nam” đến từ việc mượn hình nhạc cụ ấy làm tên hướng (giả tá).¶Dạng hiện nay có phần 冂 và 羊 biến dạng nhưng không còn liên quan đến dê. Ghi nhớ như một chữ độc lập.","a":0,"en":["south"],"f":["南"]},{"k":"北","l":5,"ch":13,"hv":"BẮC","m":"Phía bắc","on":["ホク"],"kun":["きた"],"s":5,"r":21,"rd":[21],"p":[["匕","CHỦY","Cái thìa; con dao găm",""]],"ls":"HY","o":"Hội ý: hai người (人) quay lưng vào nhau, nghĩa gốc là “quay lưng” (背 là chữ phái sinh). Vì nhà cổ quay mặt về hướng Nam, lưng quay về hướng Bắc, nên chữ được mượn để chỉ phương Bắc.¶Nghĩa gốc còn trong 敗北 (thua trận, quay lưng bỏ chạy).","a":0,"en":["north"],"f":["北"]},{"k":"時","l":5,"ch":14,"hv":"THỜI","m":"Thời gian; giờ","on":["ジ"],"kun":["とき","-どき"],"s":10,"r":72,"rd":[32,41,72],"p":[["日","NHẬT","Mặt trời; ngày",""],["寺","TỰ","Chùa",""]],"ls":"HT","o":"Hình thanh: 日 (mặt trời) chỉ nghĩa, 寺 (tự) gợi âm. Nghĩa gốc là “thời gian, mùa”, đo bằng chuyển động của mặt trời.¶Nghĩa mở rộng thành “giờ, lúc, thời kỳ” (時間, 時計, 時代). 寺 chỉ là yếu tố âm, nghĩa chùa không liên quan.","a":0,"en":["time","hour"],"f":["寺"]},{"k":"間","l":5,"ch":14,"hv":"GIAN","m":"Khoảng giữa; khoảng thời gian","on":["カン","ケン"],"kun":["あいだ","ま","あい"],"s":12,"r":169,"rd":[72,169],"p":[["門","MÔN","Cổng",""],["日","NHẬT","Mặt trời; ngày",""]],"ls":"HY","o":"Hội ý: Dạng cổ 閒 là 門 (cổng) và 月 (ánh trăng): ánh trăng lọt qua khe cổng. Về sau 月 đổi thành 日 thành 間, nghĩa gốc là khe hở, khoảng trống.¶Nghĩa mở rộng thành “khoảng giữa, thời gian, không gian” (時間, 空間, 人間).","a":0,"en":["interval","space"],"f":["間","門"]},{"k":"半","l":5,"ch":14,"hv":"BÁN","m":"Một nửa","on":["ハン"],"kun":["なか.ば"],"s":5,"r":24,"rd":[7,12,24],"p":[["丷","BÁT","Số tám; chia ra","八"],["二","NHỊ","Số hai",""],["丨","CỔN","Nét sổ thẳng",""]],"ls":"HY","o":"Hội ý: 八 (chia ra) trên 牛 (con bò). Nghĩa gốc là “chia đôi con bò (vật tế)”. Thuyết văn giải “物中分也”.¶Nghĩa mở rộng thành “một nửa” (半分, 半年) và “không trọn vẹn”. 八 ở đây vẫn mang nghĩa “phân chia”.","a":0,"en":["half","middle","odd number"],"f":["半"]},{"k":"分","l":5,"ch":14,"hv":"PHÂN","m":"Phút; chia; phần","on":["ブン","フン","ブ"],"kun":["わ.ける","わ.け","わ.かれる","わ.かる","わ.かつ"],"s":4,"r":18,"rd":[12,18],"p":[["八","BÁT","Số tám; chia ra",""],["刀","ĐAO","Con dao; thanh kiếm",""]],"ls":"HY","o":"Hội ý: 八 (chia ra) và 刀 (dao). Nghĩa gốc là “dùng dao chia vật làm đôi”. Thuyết văn giải “别也”.¶Nghĩa mở rộng thành “phần, phút, hiểu” (分かる, 部分, 十分). Ba cách đọc ブン・フン・ブ tương ứng với các nghĩa khác nhau của chữ.","a":0,"en":["part","minute of time","segment"],"f":["分"]},{"k":"今","l":5,"ch":14,"hv":"KIM","m":"Bây giờ","on":["コン","キン"],"kun":["いま"],"s":4,"r":9,"rd":[9],"p":[["亼","","",""],["㇇","","",""]],"ls":"GT","o":"Giáp cốt văn vẽ hình cái nắp úp hay cái chuông, ý nghĩa gốc không rõ. Nghĩa “bây giờ” đến từ việc mượn hình/âm của chữ này (giả tá).¶Là thành tố gợi âm trong nhiều chữ như 金, 念, 含, 吟, đều đọc gần “kin, gon, kan”.","a":0,"en":["now"],"f":["亼","今"]},{"k":"何","l":5,"ch":14,"hv":"HÀ","m":"Cái gì","on":["カ"],"kun":["なに","なん","なに-","なん-"],"s":7,"r":9,"rd":[9,30],"p":[["亻","NHÂN","Người","人"],["可","KHẢ","Có thể",""]],"ls":"HT","o":"Hình thanh: 人 (người) chỉ nghĩa, 可 (khả) gợi âm. Nghĩa gốc là “vác, gánh” (đồng nguyên với 荷). Sau này mượn làm từ nghi vấn “gì, cái gì” (giả tá).¶Chữ trong 何 (なに, なん) và 何故 (なぜ).","a":0,"en":["what"],"f":["何","可"]},{"k":"夕","l":5,"ch":14,"hv":"TỊCH","m":"Buổi chiều tối","on":["セキ"],"kun":["ゆう"],"s":3,"r":36,"rd":[36],"p":[["𠂊","","",""],["丶","CHỦ","Dấu chấm",""]],"ls":"TH","o":"Tượng hình: bắt nguồn từ chữ 月 (mặt trăng khuyết) bớt một nét. Giáp cốt văn 夕 và 月 từng dùng lẫn nhau, về sau tách ra: 月 chỉ mặt trăng, 夕 chỉ buổi tối.¶Nghĩa mở rộng thành “chiều tối” (夕方, 夕日). Cũng xuất hiện trong 外, 名, 多 với nghĩa “tối”.","a":0,"en":["evening"],"f":["夕"]},{"k":"方","l":5,"ch":14,"hv":"PHƯƠNG","m":"Phương hướng; người","on":["ホウ"],"kun":["かた","-かた","-がた"],"s":4,"r":70,"rd":[70],"p":[["亠","ĐẦU","Cái nắp; mái đầu",""],["丿","PHIỆT","Nét phẩy",""],["𠃌","","",""]],"ls":"TH","o":"Giáp cốt văn vẽ cái cày hai nhánh (lưỡi cày), hoặc hai chiếc thuyền buộc liền nhau. Nghĩa gốc “hướng, bên, vuông” là mở rộng của việc định phương hướng.¶Nghĩa mở rộng thành “phương hướng” (方向), “cách thức” (方法), “người” (あの方), “vuông” (四角: 方). Cũng là bộ thủ số 70.","a":0,"en":["direction","person","alternative"],"f":["方"]},{"k":"新","l":5,"ch":15,"hv":"TÂN","m":"Mới","on":["シン"],"kun":["あたら.しい","あら.た","あら-","にい-"],"s":13,"r":69,"rd":[69,75,117],"p":[["亲","","",""],["斤","CÂN","Cái rìu; cân",""]],"ls":"HT","o":"Dạng gốc: 斤 (cái rìu) chỉ nghĩa, 亲 (tân) gợi âm; hình ảnh chặt cây lấy củi mới. Thuyết văn giải “取木也”, nghĩa gốc là chặt cây lấy củi.¶Nghĩa mở rộng thành “mới” (新しい, 新聞, 新年), vì củi mới chặt là thứ tươi mới.","a":0,"en":["new"],"f":["新","斤"]},{"k":"古","l":5,"ch":15,"hv":"CỔ","m":"Cũ; xưa","on":["コ"],"kun":["ふる.い","ふる-","-ふる.す"],"s":5,"r":30,"rd":[24,30],"p":[["十","THẬP","Số mười",""],["口","KHẨU","Cái miệng",""]],"ls":"HY","o":"Hội ý: 十 (mười, nhiều thế hệ) và 口 (miệng, lời nói). Lời truyền miệng qua mười đời là chuyện cổ. Thuyết văn giải “故也”.¶Nghĩa mở rộng thành “cũ, xưa” (古い, 古代). Cũng là thành tố gợi âm trong 湖, 固, 個, 苦 (đọc “ko”).","a":0,"en":["old"],"f":["古"]},{"k":"長","l":5,"ch":15,"hv":"TRƯỜNG","m":"Dài; trưởng","on":["チョウ"],"kun":["なが.い","おさ"],"s":8,"r":168,"rd":[168],"p":[["一","NHẤT","Số một; nét ngang",""],["𠄌","","",""],["乀","PHIỆT","Nét phẩy","丿"],["丿","PHIỆT","Nét phẩy",""]],"ls":"TH","o":"Tượng hình: Giáp cốt văn vẽ người tóc dài, chống gậy. Nghĩa gốc là “người già, tóc dài”, từ đó mở rộng thành “dài” và “trưởng”.¶Nghĩa mở rộng thành “dài” (長い), “trưởng, đứng đầu” (社長, 校長), “lớn lên” (成長). Là bộ thủ số 168.","a":0,"en":["long","leader","superior"],"f":["長"]},{"k":"安","l":5,"ch":15,"hv":"AN","m":"Rẻ; yên ổn","on":["アン"],"kun":["やす.い","やす.まる","やす","やす.らか"],"s":6,"r":40,"rd":[38,40],"p":[["宀","MIÊN","Mái nhà",""],["女","NỮ","Phụ nữ",""]],"ls":"HY","o":"Hội ý: 宀 (mái nhà) và 女 (người phụ nữ). Người phụ nữ ở trong nhà, tượng trưng cho sự bình yên, ổn định. Thuyết văn giải “靜也”.¶Nghĩa mở rộng thành “yên” (安全, 安心) và “rẻ” (安い) vì giá rẻ khiến người ta yên lòng.","a":0,"en":["relax","cheap","low"],"f":["安","宀"]},{"k":"多","l":5,"ch":15,"hv":"ĐA","m":"Nhiều","on":["タ"],"kun":["おお.い","まさ.に","まさ.る"],"s":6,"r":36,"rd":[36],"p":[["夕","TỊCH","Buổi tối",""],["夕","TỊCH","Buổi tối",""]],"ls":"HY","o":"Hội ý: hai chữ 夕 (miếng thịt, lát thịt trên thớt) chồng lên nhau. Nghĩa là “nhiều” theo kiểu lặp chữ để chỉ số nhiều. Thuyết văn giải “重夕為多”.¶Nghĩa mở rộng thành “nhiều” (多い, 多数). Đối lập với 少 (ít).","a":0,"en":["many","frequent","much"],"f":["多","夕"]},{"k":"少","l":5,"ch":15,"hv":"THIỂU","m":"Ít","on":["ショウ"],"kun":["すく.ない","すこ.し"],"s":4,"r":42,"rd":[42],"p":[["小","TIỂU","Nhỏ bé",""],["丿","PHIỆT","Nét phẩy",""]],"ls":"CS","o":"Chỉ sự: Giáp cốt văn là những hạt nhỏ, một dạng của 小 (nhỏ) với nét phẩy thêm, nghĩa là “bớt đi một ít”. Thuyết văn giải: “不多也, 从小丿聲”.¶Nghĩa mở rộng thành “ít” (少ない), “trẻ” (少年). Đối lập với 多.","a":0,"en":["few","little"],"f":["小","少"]},{"k":"元","l":5,"ch":15,"hv":"NGUYÊN","m":"Gốc; khởi đầu","on":["ゲン","ガン"],"kun":["もと"],"s":4,"r":10,"rd":[10],"p":[["一","NHẤT","Số một; nét ngang",""],["兀","","",""]],"ls":"CS","o":"Chỉ sự: Giáp cốt văn vẽ người (儿) với dấu nhấn trên đầu (một vạch ngang ở trên), nghĩa gốc là “cái đầu”. Thuyết văn giải “始也”.¶Từ “đầu” mở rộng thành “khởi đầu, nguồn gốc” (元来, 元日) và “tinh thần, khí lực” (元気). Là bộ thủ số 10 (儿).","a":0,"en":["beginning","former time","origin"],"f":["兀","元"]},{"k":"気","l":5,"ch":15,"hv":"KHÍ","m":"Khí; tinh thần","on":["キ","ケ"],"kun":["いき","き"],"s":6,"r":84,"rd":[84],"p":[["气","KHÍ","Hơi nước; khí",""],["㐅","","",""]],"ls":"HT","o":"Dạng gốc 氣: 米 (gạo) chỉ nghĩa, 气 (khí, hơi nước) gợi âm. Nghĩa gốc là “tặng gạo cho khách”; về sau 气 là chữ chỉ hơi nước, mây, nên 氣 được dùng chỉ khí.¶気 là dạng giản lược tiếng Nhật, thay 米 bằng ×. Nghĩa mở rộng thành “hơi, tinh thần, tâm trạng” (元気, 天気, 気持ち).","a":0,"en":["spirit","mind","air"],"f":["气"]}]);
